class Solution:
    def minimumLines(self, points: List[List[int]]) -> int:
        n = len(points)
        line = [[0] * n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(n):
                if i == j:
                    line[i][j] = 1 << i
                    continue
                xj, yj = points[j]
                m = 0
                for k in range(n):
                    xk, yk = points[k]
                    if (xj - xi) * (yk - yi) == (yj - yi) * (xk - xi):
                        m |= 1 << k
                line[i][j] = m
        def go(mask):
            if mask == 0:
                return 0
            i = (mask & -mask).bit_length() - 1
            return min(1 + go(mask & ~line[i][j]) for j in range(n) if mask >> j & 1)
        return go((1 << n) - 1)

